package com.supportsphere.dao; import com.supportsphere.model.*; import com.supportsphere.util.*; import java.sql.*; import java.time.*; import java.util.*;
public class VolunteerDAO implements DAO<Volunteer,Integer>{
 private static final String SELECT="SELECT u.*,vp.experience_years,vp.availability_start,vp.availability_end,vp.verification_status,vp.rejection_reason,vp.rating,vp.rating_count FROM users u JOIN volunteer_profiles vp ON vp.volunteer_id=u.user_id ";
 public Optional<Volunteer> findById(Integer id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(SELECT+"WHERE u.user_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(c,r)):Optional.empty();}}}
 public List<Volunteer> findAll()throws Exception{List<Volunteer>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(SELECT+"WHERE u.role='VOLUNTEER' ORDER BY vp.rating DESC");ResultSet r=p.executeQuery()){while(r.next())x.add(map(c,r));}return x;}
 public void updateVerification(int id,String status)throws Exception{updateVerification(id,status,"",0);}
 public void updateVerification(int id,String status,String reason,int adminId)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{String old;String account;try(PreparedStatement p=c.prepareStatement("SELECT u.status,vp.verification_status FROM users u JOIN volunteer_profiles vp ON vp.volunteer_id=u.user_id WHERE u.user_id=? FOR UPDATE")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Volunteer profile not found.");account=r.getString("status");old=r.getString("verification_status");}}if(!"ACTIVE".equals(account))throw new IllegalStateException("Blocked volunteer accounts cannot be verified, rejected or reopened.");boolean valid=("VERIFIED".equals(status)||"REJECTED".equals(status))&&"PENDING".equals(old)||"PENDING".equals(status)&&"REJECTED".equals(old);if(!valid)throw new IllegalStateException("This verification transition is no longer available.");try(PreparedStatement p=c.prepareStatement("UPDATE volunteer_profiles SET verification_status=?,rejection_reason=? WHERE volunteer_id=?")){p.setString(1,status);p.setString(2,"REJECTED".equals(status)?reason:null);p.setInt(3,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO volunteer_verification_history(volunteer_id,old_status,new_status,reason,changed_by) VALUES(?,?,?,?,?)")){p.setInt(1,id);p.setString(2,old);p.setString(3,status);p.setString(4,reason.isBlank()?null:reason);p.setInt(5,adminId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO audit_logs(user_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)")){p.setInt(1,adminId);p.setString(2,"PENDING".equals(status)?"VOLUNTEER_APPLICATION_REOPENED":"VOLUNTEER_"+status);p.setString(3,"VOLUNTEER");p.setInt(4,id);p.setString(5,reason.isBlank()?"Verification status changed to "+status:reason);p.executeUpdate();}String message="REJECTED".equals(status)?"Your volunteer application was rejected. Reason: "+reason:"PENDING".equals(status)?"Your volunteer application is under reconsideration.":"Your volunteer application has been verified.";try(PreparedStatement p=c.prepareStatement("INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,'VOLUNTEER_VERIFICATION')")){p.setInt(1,id);p.setString(2,"Volunteer application update");p.setString(3,message);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public void updateRating(int id,int rating)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("UPDATE volunteer_profiles SET rating=((rating*rating_count)+?)/(rating_count+1),rating_count=rating_count+1 WHERE volunteer_id=?")){p.setInt(1,rating);p.setInt(2,id);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}}
 private Volunteer map(Connection c,ResultSet r)throws Exception{Volunteer v=new Volunteer(r.getInt("user_id"),r.getString("name"),r.getString("email"),r.getString("phone"),r.getString("area"),r.getString("city"),r.getString("landmark"));v.setStatus(r.getString("status"));v.setExperienceYears(r.getInt("experience_years"));v.setAvailabilityStart(r.getTime("availability_start").toLocalTime());v.setAvailabilityEnd(r.getTime("availability_end").toLocalTime());v.setVerificationStatus(r.getString("verification_status"));v.setRejectionReason(r.getString("rejection_reason"));v.setRating(r.getDouble("rating"));v.setRatingCount(r.getInt("rating_count"));try(PreparedStatement p=c.prepareStatement("SELECT s.skill_name FROM skills s JOIN volunteer_skills vs ON vs.skill_id=s.skill_id WHERE vs.volunteer_id=?")){p.setInt(1,v.getUserId());try(ResultSet x=p.executeQuery()){while(x.next())v.getSkills().add(x.getString(1));}}return v;}
}
